+static int write_file(const char *path, const void *buf, size_t count)
+{
+	int fd;
+	ssize_t ret;
+
+	fd = open(path, O_WRONLY | O_CLOEXEC | O_NOCTTY);
+	if (fd < 0)
+		return -errno;
+
+	ret = write_nointr(fd, buf, count);
+	close(fd);
+	if (ret < 0)
+		return -errno;
+	if ((size_t)ret != count)
+		return -EIO;
+
+	return 0;
+}
