+
+	err = write_file("/proc/self/setgroups", "deny", sizeof("deny") - 1);
+	if (err && errno != ENOENT)
+		return err;
+
+	snprintf(map, sizeof(map), "0 %d 1", uid);
+	err = write_file("/proc/self/uid_map", map, strlen(map));
+	if (err)
