+
+	snprintf(map, sizeof(map), "0 %d 1", gid);
+	err = write_file("/proc/self/gid_map", map, strlen(map));
+	if (err)
+		return err;
+
+	if (setgid(0))
+		return -errno;
+	if (setuid(0))
+		return -errno;
+
+	return 0;
+}
